  const colo=el('div','dl-srch-col');sh.box.insertBefore(colo,out);let tm=0,sq=0;const run=async()=>{const q=i.value.trim();sug.hidden=!!q;colo.textContent='';if(!q){out.textContent='';return;}askAnswer(q,'',out);const my=++sq;try{const m=q.match(/(?:under|below|<)\s*₹?\s*(\d+)\s*(k|l|lakh)?/i);const qq=q.replace(/(?:under|below|<)\s*₹?\s*\d+\s*(k|l|lakh)?/i,'').trim();const max=m?Number(m[1])*(/k/i.test(m[2]||'')?1000:/l/i.test(m[2]||'')?100000:1):0;const r=await window.lx.deals.catalog({q:qq,max,limit:6});if(my!==sq)return;if(r.total){const hd=el('div','dl-srch-ch');hd.appendChild(el('b',null,'In the Collection'));hd.appendChild(el('small',null,Number(r.total).toLocaleString('en-IN')+' pieces'));colo.appendChild(hd);const g=el('div','cl-grid');r.rows.forEach(it=>g.appendChild(colCard(it)));colo.appendChild(g);const all=el('button','btn dl-ask','See all '+Number(r.total).toLocaleString('en-IN')+' pieces →');all.type='button';all.addEventListener('click',()=>{sh.close();collectionPage({q,max});});colo.appendChild(all);setTimeout(()=>{[...out.querySelectorAll('*')].forEach(x=>{if(/^Nothing listed right now/.test(x.textContent||'')&&x.children.length===0){const p=x.parentElement;if(p&&p!==out)p.hidden=true;else x.hidden=true;}});},60);}}catch(e){}};
