 function themeFromLogo(dataUrl){return new Promise(res=>{const i=new Image();i.onload=()=>{const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');x.drawImage(i,0,0,64,64);const p=x.getImageData(0,0,64,64).data;const B={};let dark=0,n=0;
   for(let k=0;k<p.length;k+=4){if(p[k+3]<128)continue;const r=p[k],g=p[k+1],b=p[k+2];const mx=Math.max(r,g,b),mn=Math.min(r,g,b);n++;if(mx<60)dark++;if(mx-mn<28)continue;const key=[r>>5,g>>5,b>>5].join(',');B[key]=(B[key]||0)+1;}
   const top=Object.entries(B).sort((a,b)=>b[1]-a[1])[0];const hex=v=>'#'+v.map(z=>Math.min(255,z).toString(16).padStart(2,'0')).join('');let acc='#c9a35e';if(top){const [r,g,b]=top[0].split(',').map(z=>(+z<<5)+16);acc=hex([r,g,b]);}
   const accRgb=hex2(acc);const bg=dark/Math.max(1,n)>.35?'#f6f1ea':hex(accRgb.map(v=>Math.round(v*.18)));res({bg,acc});};i.onerror=()=>res(null);i.src=dataUrl;});}
