   y+=30;doc.setTextColor(...IVORY);doc.setFont('times','italic');doc.setFontSize(24);const tl=doc.splitTextToSize(d.title||'',W-140);doc.text(tl.slice(0,2),W/2,y,{align:'center'});y+=Math.min(2,tl.length)*26;
